/**
 * Shapes of the static data in public/data/, generated by data/build.ts.
 * Keep `Country` in sync with the `Country` interface in data/build.ts.
 * The Phase 4 backend should serve the same shapes (ADR 0001).
 */

export interface Country {
  /** ISO 3166-1 alpha-3 code (mledoze cca3; Kosovo is "UNK"). Matches the map geometry id. */
  id: string;
  /** ISO 3166-1 alpha-2 code, e.g. for flag assets. */
  iso2: string;
  name: string;
  officialName: string;
  /** Some countries have several capitals, a few have none. */
  capitals: string[];
  region: string;
  /** Empty string when the source has no subregion. */
  subregion: string;
  unMember: boolean;
  independent: boolean;
  /** km² */
  area: number;
  /** Approximate center, [latitude, longitude]. */
  latlng: [number, number];
}

/**
 * The parts of world.topo.json the app relies on. Arcs and transforms are left to the
 * TopoJSON library that renders the map.
 */
export interface WorldTopology {
  type: 'Topology';
  objects: {
    world: {
      type: 'GeometryCollection';
      /** id is a Country id, or a neutral-land code when it has no Country. */
      geometries: { id: string; type: string }[];
    };
  };
}
